// Original Actions/private D-Bus authenticated Group management boundaries.
#[tokio::test]async fn group_management_http_actual_original_peer_properties_then_disband_commit_and_join(){Box::pin(async{
 use crate::connectivity::app_voice::providers::jegotrip as n;let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let listener=tokio::net::TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&tokio_rustls::rustls::version::TLS13);let mut c=group_management_http_config(&cert.root);c["profile"]["route"]["router_common"]["reference"]=serde_json::json!(format!("Router:tls -h 127.0.0.1 -p {port} -ri 12001;"));c["profile"]["route"]["router_common"]["anchors"][0]["port"]=serde_json::json!(port);let(s,_,b)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":c})),Some(&cookie)).await;assert_eq!(s,StatusCode::CREATED);let line=created_line(&b);let(tx,rx)=tokio::sync::oneshot::channel();let peer=tokio::spawn(Box::pin(n::relation_http_test_peer::serve_group_management(listener,server,state.app.database.clone(),line.clone(),rx)));
 let(s,_,_)=account_request(&served,reqwest::Method::POST,&format!("/api/non-3gpp/accounts/{line}/start"),Some(serde_json::json!({"expected_revision":1})),Some(&cookie)).await;assert_eq!(s,StatusCode::ACCEPTED);tokio::time::timeout(std::time::Duration::from_secs(6),async{while state.app.app_accounts.get(&line,100).await.unwrap().phase!="hosted"{tokio::task::yield_now().await;}}).await.unwrap();let path=format!("/api/non-3gpp/accounts/{line}/group-management");for disband in [false,true]{let mut v=group_management_http_body();if disband{v["operation"]=serde_json::json!("disband");v["properties"]=serde_json::json!([]);v["nonce"]=serde_json::json!("c".repeat(32));v["destructive_consent"]=serde_json::json!(true);}let(s,h,b)=account_request(&served,reqwest::Method::POST,&path,Some(v.clone()),Some(&cookie)).await;assert_eq!(s,StatusCode::OK);no_store(&h);no_secrets(&b);let value:serde_json::Value=serde_json::from_str(&b).unwrap();assert_eq!(value["data"]["state"],"confirmed");assert_eq!(value["data"]["additions"],0);if disband{assert_eq!(value["data"]["base_time"],"-9223372036854775808");}else{assert!(value["data"]["base_time"].is_null());}let(s,_,b)=account_request(&served,reqwest::Method::POST,&path,Some(v),Some(&cookie)).await;assert_eq!(s,StatusCode::OK);assert_eq!(serde_json::from_str::<serde_json::Value>(&b).unwrap()["data"],value["data"]);}
 assert_eq!(state.app.database.get_recent_app_events(Some(&line),128).unwrap().iter().filter(|e|e.event_type=="app_voice.group_management_updated").count(),2);tx.send(()).unwrap();let(s,_,_)=account_request(&served,reqwest::Method::POST,&format!("/api/non-3gpp/accounts/{line}/stop"),Some(serde_json::json!({"expected_revision":1})),Some(&cookie)).await;assert_eq!(s,StatusCode::OK);peer.await.unwrap();assert!(!state.app.app_accounts.get(&line,100).await.unwrap().io_cleanup_required);
}).await;}
fn group_management_http_config(root:&str)->serde_json::Value{let mut c=relation_http_config(root);c["profile"]["group_management"]=serde_json::json!({"set_properties":true,"disband":true});c}
fn group_management_http_body()->serde_json::Value{serde_json::json!({"expected_revision":1,"group_id":"1-2","operation":"set_properties","nonce":"b".repeat(32),"properties":[{"key":"Name","value":"private-group"}],"consent":true,"write_consent":true,"destructive_consent":false})}
#[tokio::test]async fn group_management_http_auth_and_strict_fields_do_not_mint_write_or_echo_private_input(){let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let p="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/group-management";let(s,_,b)=account_request(&served,reqwest::Method::POST,p,Some(group_management_http_body()),None).await;assert_eq!(s,StatusCode::UNAUTHORIZED);no_secrets(&b);let cookie=authenticate(&served).await;for key in ["uid","token","scope","accepted","base_time","clear_unknown"]{let mut v=group_management_http_body();v[key]=serde_json::json!("private");let(s,h,b)=account_request(&served,reqwest::Method::POST,p,Some(v),Some(&cookie)).await;assert_eq!(s,StatusCode::BAD_REQUEST);no_store(&h);no_secrets(&b);assert!(!b.contains("private-group"));}assert!(state.app.app_accounts.list(100).await.unwrap().is_empty());}
#[tokio::test]async fn group_management_http_bad_shape_and_destructive_consent_are_rejected_before_admission(){let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let p="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/group-management";for mode in 0..7{let mut v=group_management_http_body();match mode{0=>v["group_id"]=serde_json::json!("1_2"),1=>v["properties"]=serde_json::json!([]),2=>v["nonce"]=serde_json::json!("A".repeat(32)),3=>v["properties"][0]=serde_json::json!({"key":"Type","value":99}),4=>v["properties"][0]=serde_json::json!({"key":"Type","value":"1"}),5=>v["operation"]=serde_json::json!("create"),_=>{v["operation"]=serde_json::json!("disband");v["properties"]=serde_json::json!([]);}}let(s,h,b)=account_request(&served,reqwest::Method::POST,p,Some(v),Some(&cookie)).await;assert_eq!(s,StatusCode::BAD_REQUEST);no_store(&h);no_secrets(&b);}assert!(state.app.app_accounts.list(100).await.unwrap().is_empty());}
#[tokio::test]async fn group_management_http_policy_is_separate_and_stopped_account_never_opens_sdk(){let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");for config in [serde_json::json!({"set_properties":false,"disband":false}),serde_json::json!({"set_properties":true,"disband":true,"ready":true})]{let mut c=group_management_http_config(&cert.root);c["profile"]["group_management"]=config;let(s,_,_)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":c})),Some(&cookie)).await;assert_eq!(s,StatusCode::BAD_REQUEST);}let(s,_,b)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":group_management_http_config(&cert.root)})),Some(&cookie)).await;assert_eq!(s,StatusCode::CREATED);let line=created_line(&b);let p=format!("/api/non-3gpp/accounts/{line}/group-management");for mode in 0..3{let mut v=group_management_http_body();if mode==0{v["consent"]=serde_json::json!(false);}if mode==1{v["expected_revision"]=serde_json::json!(2);}let(s,h,b)=account_request(&served,reqwest::Method::POST,&p,Some(v),Some(&cookie)).await;assert_eq!(s,if mode==0{StatusCode::FORBIDDEN}else if mode==1{StatusCode::CONFLICT}else{StatusCode::SERVICE_UNAVAILABLE});no_store(&h);no_secrets(&b);}assert!(state.app.app_accounts.relation_intent_history(&line,128).unwrap().is_empty());assert_eq!(state.app.app_accounts.get(&line,100).await.unwrap().phase,"stopped");}
#[tokio::test]async fn group_management_http_shared_history_exposes_operation_without_fake_member_counts_or_times(){let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let(s,_,b)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":group_management_http_config(&cert.root)})),Some(&cookie)).await;assert_eq!(s,StatusCode::CREATED);let line=created_line(&b);state.app.database.with_conn(|c|{c.execute("INSERT INTO app_voice_relation_writes(line_id,revision,user_nonce,intent_hash,identity_key,run_nonce,scope_epoch,target_kind,additions,updates,removals,state,updated_at) VALUES(?1,1,?2,zeroblob(32),zeroblob(32),'fixture','fixture','group',0,0,0,1,'2026-01-01T00:00:00Z')",rusqlite::params![line,"b".repeat(32)]).map_err(|_|"fixture")?;let id=c.last_insert_rowid();c.execute("INSERT INTO app_voice_group_write_operations(line_id,user_nonce,operation,properties,write_id) VALUES(?1,?2,'set_properties',1,?3)",rusqlite::params![line,"b".repeat(32),id]).map_err(|_|"fixture")}).unwrap();let(s,h,b)=account_request(&served,reqwest::Method::GET,&format!("/api/non-3gpp/accounts/{line}/relation-writes?limit=128"),None,Some(&cookie)).await;assert_eq!(s,StatusCode::OK);no_store(&h);no_secrets(&b);let v:serde_json::Value=serde_json::from_str(&b).unwrap();let r=&v["data"][0];assert_eq!(r["management"],serde_json::json!({"operation":"set_properties","properties":1}));assert!(r["base_time"].is_null()&&r["update_time"].is_null());assert_eq!(r["additions"],0);assert!(!b.contains(&"b".repeat(32)));}
